// Offline navigation must be answered by the precache, including the canonical entry point "/"
// (bead qrcode-to8).
//
// The precache manifest is generated by walking dist/, so on its own it lists file URLs such as
// /index.html and never "/". The install handler therefore adds the navigable entry point
// explicitly (`const urls = ['/', ...manifest.files.map(toPrecacheUrl)]` in app/sw.js), and this
// file pins that contract from the request side: a navigation to "/" with the network down has to
// resolve from the precache instead of rejecting.
//
// app/sw.js registers its listeners at import time, so the stubs are installed before the dynamic
// import. Each test file runs in its own process (see test/unit/sw-precache.test.mjs).
import test from 'node:test';
import assert from 'node:assert/strict';

const origin = 'https://qr-snapper.test';
const VERSION = '9.9.9-test';
const PRECACHE_CACHE = `qr-precache-${VERSION}`;

const listeners = new Map();
const shell = new Response('<!doctype html><title>shell</title>', {
  status: 200,
  headers: { 'content-type': 'text/html; charset=utf-8' },
});

let fetchCalls = 0;
let lastMatchOptions = null;

globalThis.__APP_VERSION__ = VERSION;
globalThis.self = {
  location: { origin },
  skipWaiting() {},
  clients: { claim() { return Promise.resolve(); } },
  registration: { unregister() { return Promise.resolve(true); } },
  addEventListener(type, handler) { listeners.set(type, handler); },
};

// The precached entry points this worker has. "/" is present because install() adds it; the file
// URLs come from the generated manifest.
const precached = new Set(['/', '/index.html', '/about.html']);

globalThis.caches = {
  async keys() { return [PRECACHE_CACHE]; },
  async delete() { return true; },
  async open() {
    return {
      async addAll() {},
      async keys() { return []; },
    };
  },
  async match(request, options = {}) {
    lastMatchOptions = options;
    const url = new URL(typeof request === 'string' ? request : request.url);
    if (options.cacheName !== PRECACHE_CACHE) return undefined;
    // Cache.match with ignoreSearch matches on the pathname only.
    const key = options.ignoreSearch ? url.pathname : `${url.pathname}${url.search}`;
    return precached.has(key) ? shell.clone() : undefined;
  },
};

// Network down: any fetch() the worker attempts must be visible as a failure, not a silent success.
globalThis.fetch = async (url) => {
  fetchCalls++;
  throw new TypeError(`network unavailable: ${String(url)}`);
};

await import('../../app/sw.js');
const onFetch = listeners.get('fetch');
assert.ok(onFetch, 'app/sw.js must register a fetch listener');

/**
 * Dispatch a synthetic navigation through the worker's fetch listener and return the response the
 * router passed to respondWith().
 * @param {string} url
 */
async function navigate(url) {
  const request = new Request(url);
  // node's undici refuses mode 'navigate' in the Request constructor; the route only reads the
  // property, so shadowing it keeps the test honest about what the worker sees.
  Object.defineProperty(request, 'mode', { value: 'navigate' });

  let responded;
  onFetch({ request, respondWith(promise) { responded = promise; } });
  assert.ok(responded, 'a same-origin navigation must be answered by the worker');

  return responded;
}

test('a navigation to / resolves from the precache with the network down', async () => {
  fetchCalls = 0;
  const response = await navigate(`${origin}/`);

  assert.equal(response.status, 200, 'offline navigation to the entry point must not fail');
  assert.equal(await response.text(), '<!doctype html><title>shell</title>');
  assert.equal(fetchCalls, 0, 'a precached navigation must not touch the network at all');
  assert.equal(lastMatchOptions.cacheName, PRECACHE_CACHE, 'only this release cache may answer');
  assert.equal(lastMatchOptions.ignoreSearch, true);
});

test('a navigation to / with a shared-link query still matches the precached entry point', async () => {
  fetchCalls = 0;
  const response = await navigate(`${origin}/?utm_source=shared`);

  assert.equal(response.status, 200);
  assert.equal(fetchCalls, 0, 'ignoreSearch must keep shared links working offline');
});

test('the precached file URLs serve offline navigations too', async () => {
  for (const path of ['/index.html', '/about.html']) {
    fetchCalls = 0;
    const response = await navigate(`${origin}${path}`);
    assert.equal(response.status, 200, `${path} must be served from the precache`);
    assert.equal(fetchCalls, 0);
  }
});

test('a path that was never precached still rejects offline, so "/" being precached is the fix', async () => {
  fetchCalls = 0;
  await assert.rejects(navigate(`${origin}/no-such-page`), /network unavailable/);
  assert.equal(fetchCalls, 1, 'an uncached path falls through to the network exactly once');
});
